            if match.group('link'):
                return "%s <%s>" % (match.group('link_text'), match.group('link_url').strip())
            if match.group('reference'):
                return match.group('reference_text')
            return '\n-------------\n'

        return cls._TTY_MACRO.sub(replace, text)

